    @FunctionalInterface
    private interface NeighborVisitor {
        void visit(int vertex, int weight);
    }

    private static final class Graph {
        private final int[][] adjacencyMatrix;

        private Graph(int[][] adjacencyMatrix) {
            this.adjacencyMatrix = adjacencyMatrix;
        }

        static Graph fromAdjacencyMatrix(int[][] adjacencyMatrix) {
            validateAdjacencyMatrix(adjacencyMatrix);
            return new Graph(copyAdjacencyMatrix(adjacencyMatrix));
        }

        static Graph sampleGraph() {
            return fromAdjacencyMatrix(new int[][] {
                { 0, 2, 0, 6, 0 },
                { 2, 0, 3, 8, 5 },
                { 0, 3, 0, 0, 7 },
                { 6, 8, 0, 0, 9 },
                { 0, 5, 7, 9, 0 }
            });
        }

        int vertexCount() {
            return adjacencyMatrix.length;
        }

        int edgeWeight(int from, int to) {
            return adjacencyMatrix[from][to];
        }

        boolean hasEdge(int from, int to) {
            return edgeWeight(from, to) != NO_EDGE;
        }

        void forEachNeighbor(int from, NeighborVisitor visitor) {
            for (int to = 0; to < vertexCount(); to++) {
                if (hasEdge(from, to)) {
                    visitor.visit(to, edgeWeight(from, to));
                }
            }
        }

        private static int[][] copyAdjacencyMatrix(int[][] adjacencyMatrix) {
            int[][] copy = new int[adjacencyMatrix.length][];
            for (int rowIndex = 0; rowIndex < adjacencyMatrix.length; rowIndex++) {
                copy[rowIndex] = Arrays.copyOf(adjacencyMatrix[rowIndex], adjacencyMatrix[rowIndex].length);
            }
            return copy;
        }
    }

    private static final class PrimState {
        private final int[] parent;
        private final int[] bestEdgeWeight;
        private final boolean[] includedInMst;

        PrimState(int vertexCount) {
            this.parent = new int[vertexCount];
            this.bestEdgeWeight = new int[vertexCount];
            this.includedInMst = new boolean[vertexCount];
            Arrays.fill(bestEdgeWeight, Integer.MAX_VALUE);
            bestEdgeWeight[START_VERTEX] = 0;
            parent[START_VERTEX] = ROOT_PARENT;
        }

        int selectNextVertex() {
            int minValue = Integer.MAX_VALUE;
            int minIndex = -1;

            for (int vertex = 0; vertex < includedInMst.length; vertex++) {
                if (!includedInMst[vertex] && bestEdgeWeight[vertex] < minValue) {
                    minValue = bestEdgeWeight[vertex];
                    minIndex = vertex;
                }
            }

            return minIndex;
        }

        void include(int vertex) {
            includedInMst[vertex] = true;
        }

        boolean isIncluded(int vertex) {
            return includedInMst[vertex];
        }

        void updateConnection(int vertex, int newParent, int edgeWeight) {
            if (!isIncluded(vertex) && edgeWeight < bestEdgeWeight[vertex]) {
                parent[vertex] = newParent;
                bestEdgeWeight[vertex] = edgeWeight;
            }
        }

        Result toResult(Graph graph) {
            List<Edge> edges = new ArrayList<>();
            int totalWeight = 0;

            for (int vertex = 1; vertex < graph.vertexCount(); vertex++) {
                int from = parent[vertex];
                int weight = graph.edgeWeight(from, vertex);

                edges.add(new Edge(from, vertex, weight));
                totalWeight += weight;
            }

            return new Result(edges, totalWeight);
        }
    }

    private static void validateAdjacencyMatrix(int[][] graph) {
        if (graph == null) {
            throw new IllegalArgumentException("Graph must not be null.");
        }

        if (graph.length == 0) {
            throw new IllegalArgumentException("Graph must contain at least one vertex.");
        }

        for (int rowIndex = 0; rowIndex < graph.length; rowIndex++) {
            int[] row = graph[rowIndex];
            if (row == null) {
                throw new IllegalArgumentException("Graph rows must not be null.");
            }

            if (row.length != graph.length) {
                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
            }

            for (int columnIndex = rowIndex + 1; columnIndex < graph.length; columnIndex++) {
                if (row[columnIndex] != graph[columnIndex][rowIndex]) {
                    throw new IllegalArgumentException(
                        "Graph must represent an undirected adjacency matrix."
                    );
                }
            }
        }
    }

    private static void relaxOutgoingEdges(Graph graph, PrimState state, int currentVertex) {
        state.include(currentVertex);
        graph.forEachNeighbor(currentVertex,
            (neighbor, edgeWeight) -> state.updateConnection(neighbor, currentVertex, edgeWeight));
    }

    static Result computeMinimumSpanningTree(int[][] graph) {
        return computeMinimumSpanningTree(Graph.fromAdjacencyMatrix(graph));
    }

    private static Result computeMinimumSpanningTree(Graph graph) {
        int vertexCount = graph.vertexCount();
        PrimState state = new PrimState(vertexCount);

        for (int count = 0; count < vertexCount - 1; count++) {
            int currentVertex = state.selectNextVertex();

            if (currentVertex == -1) {
                throw new IllegalStateException("Graph must be connected.");
            }

            relaxOutgoingEdges(graph, state, currentVertex);
        }

        return state.toResult(graph);
    }

    public static void main(String[] args)
    {
        Result result = computeMinimumSpanningTree(Graph.sampleGraph());
        result.printTo(System.out);
    }
